B=[
('الْجَارِيَةُ','Cariye',[
('كَانَتْ شَجَرَةُ الدُّرِّ جَارِيَةً تُرْكِيَّةً، اشْتَرَاهَا الصَّالِحُ أَيُّوبُ، مِنْ أَحْفَادِ أَخِي صَلَاحِ الدِّينِ.','Şecerü’d-Dürr, Selâhaddin’in kardeşinin torunlarından es-Sâlih Eyyûb’un satın aldığı Türk bir cariyeydi.'),
('وَكَانَتْ ذَكِيَّةً عَاقِلَةً، تَعْرِفُ الْقِرَاءَةَ وَالْكِتَابَةَ وَأُمُورَ السِّيَاسَةِ.','Zeki ve akıllıydı; okuma yazmayı ve siyaset işlerini bilirdi.'),
('فَأَحَبَّهَا الصَّالِحُ، وَأَعْتَقَهَا، وَتَزَوَّجَهَا.','Sâlih onu sevdi, azat etti ve onunla evlendi.'),
('وَلَمَّا صَارَ سُلْطَانًا عَلَى مِصْرَ، كَانَتْ مَعَهُ فِي كُلِّ أُمُورِهِ.','Mısır sultanı olunca bütün işlerinde onunla birlikteydi.'),
('وَكَانَ لِلسُّلْطَانِ جُنُودٌ مِنَ الْمَمَالِيكِ التُّرْكِ، يَسْكُنُونَ فِي جَزِيرَةِ الرَّوْضَةِ عَلَى النِّيلِ.','Sultanın Nil üzerindeki Ravza adasında oturan Türk Memlûklerden askerleri vardı.'),
('فَسُمُّوا الْمَمَالِيكَ الْبَحْرِيَّةَ.','Onlara Bahrî Memlûkler denildi.')]),
('الْحَمْلَةُ الصَّلِيبِيَّةُ','Haçlı seferi',[
('وَفِي سَنَةِ سِتِّمِائَةٍ وَسَبْعٍ وَأَرْبَعِينَ جَاءَ لُوِيسُ التَّاسِعُ مَلِكُ فَرَنْسَا بِجَيْشٍ عَظِيمٍ.','647 yılında Fransa kralı IX. Louis büyük bir orduyla geldi.'),
('فَأَخَذَ دِمْيَاطَ، وَسَارَ نَحْوَ الْقَاهِرَةِ.','Dimyat’ı aldı ve Kahire’ye doğru yürüdü.'),
('وَكَانَ السُّلْطَانُ الصَّالِحُ مَرِيضًا جِدًّا فِي الْمَنْصُورَةِ.','Sultan Sâlih Mansûra’da çok hastaydı.'),
('فَمَاتَ فِي أَشَدِّ أَوْقَاتِ الْحَرْبِ.','Savaşın en zor anında öldü.'),
('فَخَافَتْ شَجَرَةُ الدُّرِّ أَنْ يَضْعُفَ الْجَيْشُ إِذَا سَمِعَ بِمَوْتِهِ.','Şecerü’d-Dürr ordunun onun ölümünü duyarsa zayıflamasından korktu.'),
('فَكَتَمَتْ مَوْتَهُ، وَكَانَتْ تُصْدِرُ الْأَوَامِرَ بِخَطٍّ يُشْبِهُ خَطَّهُ.','Ölümünü gizledi ve onun yazısına benzeyen bir yazıyla emirler çıkardı.'),
('وَكَانَتْ تُدْخِلُ الطَّعَامَ إِلَى خَيْمَتِهِ كُلَّ يَوْمٍ، كَأَنَّهُ حَيٌّ.','Her gün sanki yaşıyormuş gibi çadırına yemek sokturuyordu.')]),
('الْمَنْصُورَةُ','Mansûra',[
('وَدَخَلَ الصَّلِيبِيُّونَ مَدِينَةَ الْمَنْصُورَةِ، فَظَنُّوا أَنَّهُمْ قَدِ انْتَصَرُوا.','Haçlılar Mansûra şehrine girdiler ve kazandıklarını sandılar.'),
('فَخَرَجَ عَلَيْهِمُ الْمَمَالِيكُ مِنَ الْأَزِقَّةِ الضَّيِّقَةِ، وَقَائِدُهُمْ بَيْبَرْسُ.','Memlûkler dar sokaklardan üzerlerine çıktılar; komutanları Baybars idi.'),
('فَقُتِلَ كَثِيرٌ مِنْ فُرْسَانِ الْفِرِنْجِ، وَانْهَزَمَ الْبَاقُونَ.','Frenk şövalyelerinin çoğu öldürüldü, geri kalanlar yenildi.'),
('ثُمَّ أُسِرَ الْمَلِكُ لُوِيسُ نَفْسُهُ، وَحُبِسَ فِي دَارٍ بِالْمَنْصُورَةِ.','Sonra kral Louis’nin kendisi esir alındı ve Mansûra’da bir evde hapsedildi.'),
('وَلَمْ يُطْلَقْ إِلَّا بَعْدَ أَنْ رَدَّ دِمْيَاطَ وَدَفَعَ فِدْيَةً عَظِيمَةً.','Dimyat’ı geri verip büyük bir fidye ödedikten sonra serbest bırakıldı.'),
('وَحُفِظَتْ مِصْرُ بِفَضْلِ صَبْرِ امْرَأَةٍ وَشَجَاعَةِ جُنُودٍ.','Mısır bir kadının sabrı ve askerlerin cesareti sayesinde korundu.')]),
('السُّلْطَانَةُ','Sultan hanım',[
('وَجَاءَ ابْنُ الصَّالِحِ تُورَانْشَاهُ لِيَحْكُمَ، وَلَكِنَّهُ أَسَاءَ إِلَى الْمَمَالِيكِ وَإِلَى شَجَرَةِ الدُّرِّ.','Sâlih’in oğlu Turanşah hükmetmeye geldi ama Memlûklere ve Şecerü’d-Dürr’e kötü davrandı.'),
('فَقَتَلَهُ الْمَمَالِيكُ.','Memlûkler onu öldürdü.'),
('ثُمَّ بَايَعُوا شَجَرَةَ الدُّرِّ سُلْطَانَةً عَلَى مِصْرَ.','Sonra Şecerü’d-Dürr’e Mısır sultanı olarak biat ettiler.'),
('فَكَانَتْ أَوَّلَ امْرَأَةٍ تَحْكُمُ مِصْرَ فِي الْإِسْلَامِ، وَضُرِبَتِ السِّكَّةُ بِاسْمِهَا.','İslâm’da Mısır’ı yöneten ilk kadın oldu ve onun adına para basıldı.'),
('وَلَكِنَّ الْخَلِيفَةَ الْعَبَّاسِيَّ فِي بَغْدَادَ أَرْسَلَ يَقُولُ: «إِنْ لَمْ يَكُنْ عِنْدَكُمْ رَجُلٌ، أَرْسَلْنَا إِلَيْكُمْ رَجُلًا.»','Ama Bağdat’taki Abbâsî halifesi şöyle haber gönderdi: “Sizde bir erkek yoksa size bir erkek gönderelim.”'),
('فَتَزَوَّجَتِ الْأَمِيرَ عِزَّ الدِّينِ أَيْبَكَ، وَتَنَازَلَتْ لَهُ عَنِ الْعَرْشِ بَعْدَ ثَمَانِينَ يَوْمًا.','Emir İzzeddin Aybek’le evlendi ve seksen gün sonra tahttan onun lehine çekildi.')]),
('النِّهَايَةُ','Son',[
('وَلَكِنَّهَا بَقِيَتْ تَحْكُمُ مِنْ وَرَاءِ أَيْبَكَ سَنَوَاتٍ.','Ama yıllarca Aybek’in arkasından hükmetmeye devam etti.'),
('ثُمَّ سَمِعَتْ أَنَّ أَيْبَكَ يُرِيدُ أَنْ يَتَزَوَّجَ امْرَأَةً أُخْرَى، بِنْتَ أَمِيرِ الْمَوْصِلِ.','Sonra Aybek’in başka bir kadınla, Musul emirinin kızıyla evlenmek istediğini duydu.'),
('فَغَارَتْ وَخَافَتْ عَلَى سُلْطَانِهَا، فَدَبَّرَتْ قَتْلَهُ فِي الْحَمَّامِ.','Kıskandı ve iktidarı için korktu; hamamda onun öldürülmesini tasarladı.'),
('فَغَضِبَ الْمَمَالِيكُ وَأُمُّ ابْنِ أَيْبَكَ، فَقُتِلَتْ شَجَرَةُ الدُّرِّ سَنَةَ سِتِّمِائَةٍ وَخَمْسٍ وَخَمْسِينَ.','Memlûkler ve Aybek’in oğlunun annesi öfkelendi; Şecerü’d-Dürr 655 yılında öldürüldü.'),
('وَدُفِنَتْ فِي قَبْرٍ بَنَتْهُ لِنَفْسِهِ فِي الْقَاهِرَةِ، وَمَا زَالَ قَائِمًا إِلَى الْيَوْمِ.','Kahire’de kendisi için yaptırdığı türbeye gömüldü; türbe bugün hâlâ ayaktadır.'),
('وَيَرَى زَيْدَانُ فِي قِصَّتِهَا كَيْفَ يَرْفَعُ الذَّكَاءُ صَاحِبَهُ، وَكَيْفَ يُهْلِكُهُ الطَّمَعُ.','Zeydân onun hikâyesinde zekânın sahibini nasıl yükselttiğini, hırsın da onu nasıl helak ettiğini görür.')]),
]
